render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(from = cfg$x, to = cfg$y), c("from", "to")); from_values <- as.character(data[[cfg$x]]); to_values <- as.character(data[[cfg$y]]); nodes <- unique(c(from_values, to_values)); ang <- seq(0, 2 * pi, length.out = length(nodes) + 1)[-(length(nodes) + 1)]; xy <- data.frame(node = nodes, x = cos(ang), y = sin(ang)); from <- xy[match(from_values, xy$node), ]; to <- xy[match(to_values, xy$node), ]; chart_open_device(cfg$outputPath, cfg$format); plot(xy$x, xy$y, type = "n", axes = FALSE, xlab = "", ylab = "", main = cfg$title %||% "关系网络"); segments(from$x, from$y, to$x, to$y, col = "#CBD5E1"); points(xy$x, xy$y, pch = 21, bg = cfg$color %||% "#0A84FF", col = "white", cex = 2); text(xy$x, xy$y, labels = xy$node, pos = 3, cex = 0.9); box(); grDevices::dev.off(); cfg$outputPath }
